def has_1pos_and_kwonly(func):
    """Check if a function has exactly 1 positional argument
       and one or more keyword-only arguments."""
    if PY2:
        spec = inspect.getargspec(func)
        return len(spec.args) == 1 and bool(spec.keywords)
    else:
        spec = inspect.signature(func)
        params = list(spec.parameters.values())
        if not params:
            return False
        first = params[0]
        if first.kind not in (first.POSITIONAL_ONLY, first.POSITIONAL_OR_KEYWORD):
            return False
        for p in params[1:]:
            if p.kind != p.KEYWORD_ONLY:
                return False
        return len(params) > 1

